here<-dirname(normalizePath(sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)),winslash='/'));source(file.path(here,'../R/common.R'))
a<-args_named();src<-normal(need(a,'source-manifest'));out<-normal(need(a,'out'),FALSE);stopifnot(!dir.exists(out));dir.create(out,recursive=TRUE)
exe<-file.path(R.home('bin'),'Rscript.exe');bundle<-file.path(out,'bundle');relocated<-file.path(out,'relocated source with spaces')
stopifnot(system2(exe,c(shQuote(normal(file.path(here,'../R/export_source_bundle.R'))),'--source-manifest',shQuote(src),'--out',shQuote(bundle),'--test-mode','yes'))==0)
stopifnot(system2(exe,c(shQuote(normal(file.path(here,'../R/import_source_bundle.R'))),'--bundle',shQuote(bundle),'--out',shQuote(relocated)))==0)
old<-read.csv(src);new<-read.csv(file.path(relocated,'manifest.csv'));stopifnot(nrow(new)==2)
mask_weather<-function(z)map_nodes(z,function(q){if(type_is(q,'Models.Climate.Weather'))q$FileName<-'<weather>';q})
for(i in seq_len(nrow(new))){
 j<-which(old$source==new$source[i]&old$profile_id==new$profile_id[i]);stopifnot(length(j)==1)
 x<-fromJSON(old$input_file[j],simplifyVector=FALSE);y<-fromJSON(new$input_file[i],simplifyVector=FALSE)
 stopifnot(identical(mask_weather(x),mask_weather(y)),new$upstream_md5[i]==old$input_md5[j],md5(new$input_file[i])==new$input_md5[i])
 stopifnot(md5(node(x,'Models.Climate.Weather')$FileName)==md5(node(y,'Models.Climate.Weather')$FileName))
}
writej(list(status='PASS',profiles=2,path_with_spaces=TRUE,all_nonweather_fields_identical=TRUE,weather_bytes_identical=TRUE,scope='Round-trip source packaging only; relocated simulation-to-figures test remains pending.'),file.path(out,'QA.json'))
cat('Bundle round-trip test PASS\n')
